import java.util.*;

class Solution {
    public int findLargestSetOfOnionBags(int[] onionBags) {
        Set<Long> s = new HashSet<>();
        for (int v : onionBags) s.add((long) v);
        int best = 1;
        for (int v : onionBags) {
            if (v == 1) continue; // 1*1 == 1 would loop forever
            long cur = v;
            int length = 1;
            while (s.contains(cur * cur)) { // cur <= 1e9, so cur*cur fits in long
                cur = cur * cur;
                length++;
            }
            best = Math.max(best, length);
        }
        return best >= 2 ? best : -1;
    }
}

class Solution {
public:
    int findLargestSetOfOnionBags(vector<int>& onionBags) {
        unordered_set<long long> s(onionBags.begin(), onionBags.end());
        int best = 1;
        for (int v : onionBags) {
            if (v == 1) continue; // 1*1 == 1 would loop forever
            long long cur = v;
            int length = 1;
            while (s.count(cur * cur)) { // cur <= 1e9, so cur*cur fits in long long
                cur = cur * cur;
                length++;
            }
            best = max(best, length);
        }
        return best >= 2 ? best : -1;
    }
};
